CREATE OR REPLACE FUNCTION public.phase6_shortage_snapshot(_bom_id uuid) RETURNS TABLE(bom_item_id uuid, component_id uuid, mpn text, required_quantity numeric, on_hand numeric, reserved numeric, quality_hold numeric, open_po numeric, available numeric, shortage numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ WITH bom AS (SELECT i.id, i.matched_component_id, i.mpn, i.quantity::numeric AS required_quantity FROM public.project_bom_items i WHERE i.bom_id = _bom_id), stock AS (SELECT l.component_id, COALESCE(sum(l.quantity),0)::numeric AS on_hand FROM public.locations l GROUP BY l.component_id), reserved AS (SELECT r.component_id, COALESCE(sum(r.quantity),0)::numeric AS reserved FROM public.inventory_reservations r WHERE r.status = 'ACTIVE' GROUP BY r.component_id), hold AS (SELECT il.component_id, COALESCE(sum(il.quantity_available),0)::numeric AS quality_hold FROM public.inventory_lots il WHERE il.quality_status <> 'AVAILABLE' GROUP BY il.component_id), openpo AS (SELECT poi.component_id, COALESCE(sum(GREATEST(poi.quantity_ordered - poi.quantity_received - poi.quantity_rejected,0)),0)::numeric AS open_po FROM public.purchase_order_items poi JOIN public.purchase_orders po ON po.id=poi.po_id WHERE po.status IN ('DRAFT','SENT','PARTIALLY_RECEIVED') GROUP BY poi.component_id) SELECT b.id, b.matched_component_id, b.mpn, b.required_quantity, COALESCE(s.on_hand,0), COALESCE(r.reserved,0), COALESCE(h.quality_hold,0), COALESCE(o.open_po,0), GREATEST(COALESCE(s.on_hand,0)-COALESCE(r.reserved,0)-COALESCE(h.quality_hold,0),0), GREATEST(b.required_quantity-GREATEST(COALESCE(s.on_hand,0)-COALESCE(r.reserved,0)-COALESCE(h.quality_hold,0),0)-COALESCE(o.open_po,0),0) FROM bom b LEFT JOIN stock s ON s.component_id=b.matched_component_id LEFT JOIN reserved r ON r.component_id=b.matched_component_id LEFT JOIN hold h ON h.component_id=b.matched_component_id LEFT JOIN openpo o ON o.component_id=b.matched_component_id; $$;
CREATE OR REPLACE FUNCTION public.create_purchase_request_from_bom_shortage(_bom_id uuid, _required_date date DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_pr_id uuid; v_project_id uuid; v_department_id uuid; v_number text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT b.project_id INTO v_project_id FROM public.project_boms b WHERE b.id = _bom_id; IF v_project_id IS NULL THEN RAISE EXCEPTION 'BOM not found'; END IF; SELECT id INTO v_department_id FROM public.departments WHERE code IN ('PUR','PD','PUR/PD') AND is_active ORDER BY CASE code WHEN 'PUR' THEN 0 WHEN 'PD' THEN 1 ELSE 2 END LIMIT 1; v_number := public.next_business_number('purchase_request'); INSERT INTO public.purchase_requests(request_number, source_type, source_entity_id, project_id, bom_id, department_id, requester_id, status, required_date, notes) VALUES (v_number,'BOM_SHORTAGE',_bom_id,v_project_id,_bom_id,v_department_id,auth.uid(),'DRAFT',_required_date,'Generated from BOM shortage snapshot') RETURNING id INTO v_pr_id; INSERT INTO public.purchase_request_items(purchase_request_id,component_id,mpn,required_quantity,shortage_quantity) SELECT v_pr_id, component_id, mpn, required_quantity, shortage FROM public.phase6_shortage_snapshot(_bom_id) WHERE shortage > 0; IF NOT EXISTS (SELECT 1 FROM public.purchase_request_items WHERE purchase_request_id=v_pr_id) THEN RAISE EXCEPTION 'No purchase shortage found for BOM'; END IF; RETURN v_pr_id; END; $$;
REVOKE ALL ON FUNCTION public.phase6_shortage_snapshot(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.phase6_shortage_snapshot(uuid) TO authenticated, service_role; REVOKE ALL ON FUNCTION public.create_purchase_request_from_bom_shortage(uuid,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_purchase_request_from_bom_shortage(uuid,date) TO authenticated, service_role;